#[derive(Debug, thiserror::Error)]
pub enum ExecError {
    #[error("instantiation failed: {0}")]
    Instantiate(Box<wasmer::InstantiationError>),
    #[error("missing export: {0}")]
    Export(#[from] wasmer::ExportError),
    #[error("cannot create the imported memory: {0}")]
    Memory(#[from] MemoryError),
    #[error("no registered ABI serves this module")]
    NoAbi,
    #[error("cannot copy a forked process's instance: {0}")]
    Fork(String),
    /// The host panicked while running the process; its thread group was killed.
    #[error("the host panicked: {0}")]
    Panic(String),
}

impl From<wasmer::InstantiationError> for ExecError {
    fn from(err: wasmer::InstantiationError) -> Self {
        Self::Instantiate(Box::new(err))
    }
}

/// Host state behind every import of one instance.
pub struct ExecEnv<S> {
    syscalls: Arc<S>,
    task: TaskId,
    /// `task`'s work flag, read on every return to the guest.
    work: Arc<WorkFlag>,
    memory: Option<Memory>,
    /// The instance's half of its ABI; set once the instance exists.
    abi: Option<Arc<dyn AbiInstance<S>>>,
    // ---- thr ----
    /// What new threads of the process instantiate, when its memory is shared.
    threads: Option<Arc<dyn thread::Start>>,
    // ---- proc ----
    proc: process::ProcExports,
    /// The unwind state of an asyncify instance, `None` in the other build configurations.
    asyncify: Option<asyncify::Asyncify>,
    /// What the ABI's import that forks hands its resumption in the child
    /// ([`asyncify::import::set_fork_payload`]).
    fork_payload: Option<asyncify::Tag>,
}

impl<S: Control> ExecEnv<S> {
    pub(crate) fn new(syscalls: Arc<S>, task: TaskId, proc: process::ProcExports) -> Self {
        Self {
            work: syscalls.work_flag(task),
            syscalls,
            task,
            memory: None,
            abi: None,
            threads: None,
            proc,
            asyncify: None,
            fork_payload: None,
        }
    }

    /// The instance runs as `task` from now on.
    pub(crate) fn switch(&mut self, task: TaskId) {
        self.work = self.syscalls.work_flag(task);
        self.task = task;
    }
}

impl<S> ExecEnv<S> {
    pub fn syscalls(&self) -> &Arc<S> {
        &self.syscalls
    }

    /// The task the instance runs as; it changes when vfork switches the instance.
    pub fn task(&self) -> TaskId {
        self.task
    }

    /// The instance's half of its ABI, for the ABI's import shims.
    pub fn abi(&self) -> Option<&Arc<dyn AbiInstance<S>>> {
        self.abi.as_ref()
    }
}

/// The syscalls object and the current task of the instance behind `env`, which every import
/// reads on entry.
pub async fn caller_parts<S: 'static>(env: &AsyncFunctionEnvMut<ExecEnv<S>>) -> (Arc<S>, TaskId) {
    let env = env.read().await;
    (env.data().syscalls.clone(), env.data().task)
}

/// Calls `function` in the instance behind `env` from inside one of its imports, such as a
/// signal handler, as a level of its own ([`asyncify`]). Every call an ABI makes into the guest
/// from an import goes through here.
pub async fn call_guest<S: 'static>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
    function: &Function,
    args: &[Value],
) -> Result<Box<[Value]>, RuntimeError> {
    asyncify::call(env, None, function, args).await
}

/// Raised from an import to unwind the guest after its thread group exited.
#[derive(Debug, thiserror::Error)]
#[error("thread group exited with status {0}")]
struct Exited(i32);

/// Compiles `wasm` for [`run`], with the preemption points that let a busy guest notice signals
/// and the exit of its thread group, and atomic waits that a signal interrupts.
pub fn load(engine: &Engine, wasm: &[u8]) -> Result<Module, CompileError> {
    Module::new(engine, instrument(wasm))
}

/// `wasm` with the preemption points [`load`] adds, for an embedder that compiles (and caches)
/// modules itself. A module compiled without them runs, but a guest that computes without
/// making syscalls, or blocks in `memory.atomic.wait`, does not notice signals or its group's
/// exit.
pub fn instrument(wasm: &[u8]) -> Cow<'_, [u8]> {
    preempt::instrument(wasm)
}

/// Runs `module`, a `wasixv2` program which [`load`] compiled, as `task` until its thread group
/// exits, and returns the exit status: the status of `exit_group`, or 128 + the signal that
/// killed it, a trap of the guest included (SIGSEGV for a bad memory access, SIGILL for
/// `unreachable`, and so on). Threads the guest creates run where `host`'s executor starts
/// them, and so do the images of vfork children; images that `execve` loads replace `module`.
///
/// Fails when `module` cannot be instantiated, after the kernel ended the process as it does
/// for a fault; or when the host panicked.
pub async fn run<S>(
    store: Store,
    module: &Module,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
) -> Result<i32, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    let abis = Arc::new(Abis::wasixv2());
    run_with_abis(store, module, syscalls, task, host, abis).await
}

/// [`run`] for a program of any ABI in `abis`, which also serves the images it loads.
pub async fn run_with_abis<S>(
    store: Store,
    module: &Module,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
    abis: Arc<Abis<S>>,
) -> Result<i32, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    let run = process::run(store, module, syscalls.clone(), task, host, abis);
    catch_panic(run)
        .await
        .unwrap_or_else(|panic| Err(host_panicked(&*syscalls, task, panic)))
}

/// How one image's run ended.
pub(crate) enum Ended {
    /// The task's thread group, or for a thread the task itself, exited.
    Exited(i32),
    /// `execve` replaced the image.
    Exec(Vec<u8>),
    /// The guest trapped while the instance ran as `task`: a hardware fault, signal `signal`.
    /// `report` says what happened, for the host when the fault kills the process.
    Fault {
        task: TaskId,
        signal: i32,
        report: String,
    },
}

/// How an image's run ended, from how the call of its entry point in the instance behind `cx`
/// did. `on_return` is what the ABI makes of the entry returning, the entry of a `role`.
async fn ended<S: Syscalls + Control + Send + Sync + 'static>(
    cx: &asyncify::Outside<'_, S>,
    result: Result<(), RuntimeError>,
    on_return: EntryReturn,
    role: Role,
) -> Ended {
    let err = match (result, on_return) {
        (Ok(()), EntryReturn::Exit(status)) => return exit_on_return(cx, role, status).await,
        // Linux kills a process whose entry point returns with SIGSEGV, as it runs into
        // whatever follows.
        (Ok(()), EntryReturn::Fault) => {
            tracing::warn!("the guest returned from its entry point");
            RuntimeError::new("the guest returned from its entry point")
        }
        (Err(err), _) => err,
    };
    let err = match err.downcast::<Exited>() {
        Ok(Exited(status)) => return Ended::Exited(status),
        Err(err) => err,
    };
    let err = match err.downcast::<process::ExecNew>() {
        Ok(process::ExecNew(image)) => return Ended::Exec(image),
        Err(err) => err,
    };
    let task = cx.with(|env, _| env.task).await;
    let message = err.to_string();
    let signal = fault_signal(err);
    tracing::debug!(tid = task.0, signal, "guest trapped: {message}");
    let report = format!(
        "wasixv2: thread {} trapped, killing its process with {}: {message}",
        task.0,
        signal_name(signal)
    );
    Ended::Fault {
        task,
        signal,
        report,
    }
}

/// The entry point returned where the ABI makes that an exit with `status`: the task exits as
/// if the guest had called `exit_group` (for a process image) or `exit` (for a thread).
async fn exit_on_return<S: Syscalls + Control + Send + Sync + 'static>(
    cx: &asyncify::Outside<'_, S>,
    role: Role,
    status: i32,
) -> Ended {
    let (syscalls, task) = cx.with(|env, _| (env.syscalls.clone(), env.task)).await;
    let memory = memory::OutsideMemory { cx };
    let caller = Caller::new(task, &memory);
    // Neither call fails; the exit they leave pending is what ends the task.
    let _ = match role {
        Role::Process => syscalls.exit_group(&caller, status).await,
        Role::Thread => syscalls.exit(&caller, status).await,
    };
    Ended::Exited(process::exit_status(&*syscalls, task))
}

fn signal_name(signal: i32) -> &'static str {
    match Signal(signal) {
        Signal::SIGILL => "SIGILL",
        Signal::SIGFPE => "SIGFPE",
        Signal::SIGBUS => "SIGBUS",
        _ => "SIGSEGV",
    }
}

/// The signal a trap stands for, as the processor's exception would raise it on Linux.
fn fault_signal(err: RuntimeError) -> i32 {
    let signal = match err.to_trap() {
        Some(TrapCode::IntegerDivisionByZero | TrapCode::IntegerOverflow) => Signal::SIGFPE,
        // `ud2` and `__builtin_trap`.
        Some(TrapCode::UnreachableCodeReached) => Signal::SIGILL,
        Some(TrapCode::UnalignedAtomic | TrapCode::HeapMisaligned) => Signal::SIGBUS,
        // Bad accesses, the stack running out, calls through bad pointers, and everything the
        // host cannot run on: a signal frame that does not fit, an exception nobody caught.
        _ => Signal::SIGSEGV,
    };
    signal.0
}

/// Reports a host panic and kills the thread group of `task` with SIGSEGV, as a kernel oops
/// kills the task it hit (`make_task_dead`).
fn host_panicked<S: Control>(syscalls: &S, task: TaskId, panic: Box<dyn Any + Send>) -> ExecError {
    let message = panic
        .downcast_ref::<&str>()
        .map(|s| s.to_string())
        .or_else(|| panic.downcast_ref::<String>().cloned())
        .unwrap_or_else(|| "a panic without a message".to_string());
    tracing::error!(tid = task.0, "the host panicked running a guest: {message}");
    // The kernel's state may be what panicked; a second panic changes nothing.
    let _ = catch_unwind(AssertUnwindSafe(|| {
        process::fault(syscalls, task, Signal::SIGSEGV.0);
        syscalls.release(task);
    }));
    ExecError::Panic(message)
}

/// Polls `future`, turning a panic into an error.
async fn catch_panic<F: Future>(future: F) -> Result<F::Output, Box<dyn Any + Send>> {
    let mut future = pin!(future);
    std::future::poll_fn(move |cx| {
        match catch_unwind(AssertUnwindSafe(|| future.as_mut().poll(cx))) {
            Ok(Poll::Ready(value)) => Poll::Ready(Ok(value)),
            Ok(Poll::Pending) => Poll::Pending,
            Err(panic) => Poll::Ready(Err(panic)),
        }
    })
    .await
}

/// Instantiates one image of `task`'s process and runs it from its ABI's entry point until it
/// exits, traps or `execve` replaces it.
async fn run_image<S>(
    store: Store,
    module: &Module,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
    abis: Arc<Abis<S>>,
) -> Result<Ended, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    let ready = instantiate(store, module, syscalls, task, host, abis, None)?;
    Ok(ready.start().await)
}

/// Runs a fork child from `image`, the copy of its parent's instance, until it exits, traps or
/// `execve` replaces its image.
async fn run_forked<S>(
    store: Store,
    image: asyncify::ForkImage,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
    abis: Arc<Abis<S>>,
) -> Result<Ended, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    let module = image.module.clone();
    let ready = instantiate(store, &module, syscalls, task, host, abis, Some(&image))?;
    let (entry, args, buffer) = (image.entry, image.args.clone(), image.buffer());
    drop(image);
    ready.resume_fork(entry, args, buffer).await
}

/// An instance of a process image, ready to run.
struct Ready<S: 'static> {
    store: Store,
    env: FunctionEnv<ExecEnv<S>>,
    instance: Instance,
    abi: Arc<dyn AbiInstance<S>>,
}

/// Instantiates `module` as `task` for the ABI in `abis` that serves it, or, with `fork`, the
/// copy of an instance a forked child rewinds.
fn instantiate<S>(
    mut store: Store,
    module: &Module,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
    abis: Arc<Abis<S>>,
    fork: Option<&asyncify::ForkImage>,
) -> Result<Ready<S>, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    let abi = abis.require(module)?;
    let spawner = process::spawner(
        store.engine().clone(),
        syscalls.clone(),
        host.clone(),
        abis.clone(),
    );
    let env = FunctionEnv::new(
        &mut store,
        ExecEnv::new(syscalls.clone(), task, process::ProcExports::new(spawner)),
    );
    let mut imports = imports(&*abi, &mut store, &env, module);
    let size = fork.map(|image| image.memory.len() as u64);
    let imported = import_memory(&mut store, module, &mut imports, size)?;
    let instance = Instance::new(&mut store, module, &imports)?;
    let memory = match imported {
        Some(memory) => memory,
        None => instance.exports.get_memory("memory")?.clone(),
    };
    let mut asyncify = asyncify::Asyncify::new(&instance, &mut store)?;
    if let Some(image) = fork {
        copy_image(&mut store, &instance, &memory, image)?;
        if let Some(asyncify) = &mut asyncify {
            image.adopt(asyncify);
        }
    }
    let bound = abi.bind(&instance, &mut store, task, Role::Process)?;
    // ---- thr ----
    let threads = memory.as_shared(&store).map(|shared| {
        let image = thread::Image::new(&store, module, shared, syscalls, host, abi, abis);
        image as Arc<dyn thread::Start>
    });
    let data = env.as_mut(&mut store);
    data.memory = Some(memory);
    data.abi = Some(bound.clone());
    data.threads = threads;
    data.proc.set_module(module);
    data.asyncify = asyncify;
    Ok(Ready {
        store,
        env,
        instance,
        abi: bound,
    })
}

/// Fills a fresh instance with a forked parent's memory and globals.
fn copy_image(
    store: &mut Store,
    instance: &Instance,
    memory: &Memory,
    image: &asyncify::ForkImage,
) -> Result<(), ExecError> {
    let size = memory.view(&*store).data_size();
    let missing = (image.memory.len() as u64).saturating_sub(size);
    if missing > 0 {
        let pages = missing.div_ceil(wasixv2_syscalls::WASM_PAGE_SIZE) as u32;
        memory.grow(&mut *store, pages)?;
    }
    memory
        .view(&*store)
        .write(0, &image.memory)
        .map_err(|err| ExecError::Fork(err.to_string()))?;
    for (name, value) in &image.globals {
        let global = instance.exports.get_global(name)?;
        global
            .set(&mut *store, value.clone())
            .map_err(|err| ExecError::Fork(err.to_string()))?;
    }
    Ok(())
}

impl<S: Syscalls + Control + Send + Sync + 'static> Ready<S> {
    /// Runs the image from its ABI's entry point until it exits, traps or `execve` replaces it.
    async fn start(self) -> Ended {
        let store = self.store.into_async();
        let entry = Entry::new(&self.env, &store);
        let result = self.abi.start(&entry).await;
        let on_return = self.abi.on_entry_return();
        ended(entry.cx(), result, on_return, Role::Process).await
    }

    /// Rewinds a forked child's copied stack, from `buffer`, into the export `entry` the
    /// parent forked under, and runs it until the image exits, traps or `execve` replaces it.
    async fn resume_fork(
        self,
        entry: &'static str,
        args: Vec<Value>,
        buffer: u32,
    ) -> Result<Ended, ExecError> {
        let function = self.instance.exports.get_function(entry)?.clone();
        let store = self.store.into_async();
        let cx = asyncify::Outside {
            env: &self.env,
            store: &store,
        };
        let result = match asyncify::start_rewind(&cx, buffer).await {
            Ok(()) => asyncify::call(&cx, Some(entry), &function, &args)
                .await
                .map(drop),
            Err(err) => Err(err),
        };
        let on_return = self.abi.on_entry_return();
        Ok(ended(&cx, result, on_return, Role::Process).await)
    }
}

/// The imports of one instance of `module`: its ABI's, the hook of the preemption points, and
/// the imports its atomic waits and notifies became.
fn imports<S>(
    abi: &dyn Abi<S>,
    store: &mut Store,
    env: &FunctionEnv<ExecEnv<S>>,
    module: &Module,
) -> Imports
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    let mut imports = abi.imports(store, env, module);
    imports.define(
        preempt::HOOK_MODULE,
        preempt::HOOK_NAME,
        Function::new_typed_with_env_async(store, env, preempt_point::<S>),
    );
    atomics::define(&mut imports, store, env);
    imports
}

/// Creates the memory `module` imports, if any, with the limits and sharing its import declares,
/// and at least `size` bytes. libc-built guests import a shared memory so threads can share it;
/// others export `memory`.
fn import_memory(
    store: &mut Store,
    module: &Module,
    imports: &mut Imports,
    size: Option<u64>,
) -> Result<Option<Memory>, MemoryError> {
    let Some(import) = module.imports().memories().next() else {
        return Ok(None);
    };
    let mut ty = *import.ty();
    if let Some(size) = size {
        let pages = size.div_ceil(wasixv2_syscalls::WASM_PAGE_SIZE) as u32;
        ty.minimum = ty.minimum.max(Pages(pages));
    }
    let memory = Memory::new(store, ty)?;
    imports.define(import.module(), import.name(), memory.clone());
    Ok(Some(memory))
}

/// A preemption point whose budget ran out: the guest lets the host's executor run what else
/// is ready on its thread (timers, a sibling's work), as a timer interrupt would, then takes the
/// return-to-guest path with no call to finish. Returns the next budget.
async fn preempt_point<S>(env: AsyncFunctionEnvMut<ExecEnv<S>>) -> Result<i32, RuntimeError>
where
    S: Syscalls + Control + 'static,
{
    let (syscalls, task, ready) = {
        let env = env.read().await;
        let data = env.data();
        // Still instantiating: nothing can be delivered yet. Nor while asyncify unwinds or
        // rewinds the stack: the checks were added after its instrumentation, so they run on
        // the way, and a handler called then would find the instance mid-rewind.
        let ready = data.memory.is_some() && !data.asyncify.as_ref().is_some_and(|a| a.moving());
        (data.syscalls.clone(), data.task, ready)
    };
    yield_now().await;
    if ready {
        let ret: SysResult<i32> = Ok(0);
        if let Some(Err(err)) = return_to_guest(&env, &*syscalls, task, ret).await {
            return Err(err);
        }
    }
    Ok(preempt::BUDGET)
}

/// Pending once, so the executor polls its other work before the guest goes on.
async fn yield_now() {
    let mut yielded = false;
    std::future::poll_fn(|cx| match std::mem::replace(&mut yielded, true) {
        true => Poll::Ready(()),
        false => {
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    })
    .await
}

/// How a syscall made through an import ends, once the return-to-guest path ran.
#[derive(Debug)]
pub enum Outcome<T> {
    /// A signal interrupted the call and Linux would restart it: make the call again.
    Rerun,
    /// The call saved how it goes on (`ERESTART_RESTARTBLOCK`) and no handler stopped it: make
    /// [`Syscalls::restart_syscall`] instead, and complete its result.
    Restart,
    /// The call returns this to the guest. Restarts are resolved: an interrupted call that
    /// must not restart is `EINTR` here.
    Return(Result<T, Errno>),
    /// The instance now runs as another task ([`ExecEnv::task`]), and the call returns this
    /// value to it: 0 to a vfork child, or to a vfork parent its ABI resumes by returning
    /// ([`VforkResume::ReturnSuccess`]).
    Switched(i32),
    /// The import must raise this error: the thread group exited, `execve` replaced the image,
    /// or the guest unwound (`siglongjmp`, the vfork return).
    Unwind(RuntimeError),
    /// The guest's stack unwinds for asyncify (a fork): the import returns any value, and the
    /// guest calls it again when it rewinds, where [`asyncify::resumed`] tells it how the call
    /// ended.
    Unwinding,
}

/// The return-to-guest path: runs the work the kernel left for `task` (exit, thread start,
/// task switches, new images, signal handlers), then decides how the syscall that returned
/// `ret` ends. Every import, of any ABI, calls this after each syscall.
pub async fn complete<S: Syscalls + Control + 'static, T>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
    syscalls: &S,
    task: TaskId,
    ret: SysResult<T>,
) -> Outcome<T> {
    let mut ret = ret;
    let mut task = task;
    // The value a task switch made the call return, which replaces `ret`.
    let mut switched: Option<i32> = None;
    // Once a handler ran: whether the call runs again. The first handler, the one that
    // interrupted the call, decides by its `SA_RESTART`, and any handler may cancel the restart
    // through its frame. `ERESTARTNOHAND` and `ERESTART_RESTARTBLOCK` never restart after a
    // handler.
    let mut handled: Option<bool> = None;
    // Nothing to do unless the kernel raised the flag (`exit_to_user_mode_prepare`).
    let raised = env.read().await.data().work.is_raised();
    while let Some(action) = raised.then(|| syscalls.take_pending(task)).flatten() {
        match action {
            GuestAction::Exit(status) => {
                return Outcome::Unwind(RuntimeError::user(Box::new(Exited(status))));
            }
            GuestAction::StartThread {
                task: child,
                start_arg,
            } => {
                if !thread::start(env, syscalls, child, start_arg).await {
                    ret = Err(SysErr::Errno(Errno::EAGAIN));
                }
            }
            // ---- proc ----
            GuestAction::SwitchTask {
                task: to,
                ret: value,
            } => {
                process::switch(env, to).await;
                task = to;
                switched = Some(value);
            }
            GuestAction::Exec { vfork_parent } => {
                let image = syscalls.take_image(task).unwrap_or_default();
                let Some(parent) = vfork_parent else {
                    return Outcome::Unwind(RuntimeError::user(Box::new(process::ExecNew(image))));
                };
                process::spawn_image(env, task, image).await;
                match vfork_resume(env, parent, task).await {
                    VforkResume::Unwind(err) => return Outcome::Unwind(err),
                    VforkResume::ReturnSuccess => (task, switched) = (parent, Some(0)),
                }
            }
            GuestAction::Fork {
                child,
                parent_tid,
                child_tid,
                tls,
            } => {
                // The guest unwinds now; the import that forked resumes once it rewinds.
                return match fork::start(env, syscalls, child, parent_tid, child_tid, tls).await {
                    Ok(()) => Outcome::Unwinding,
                    Err(SysErr::Errno(errno)) => Outcome::Return(Err(errno)),
                    Err(_) => unreachable!("fork fails with an errno"),
                };
            }
            GuestAction::VforkReturn { parent, child } => {
                // The child ended; nothing runs as it any more.
                syscalls.release(child);
                match vfork_resume(env, parent, child).await {
                    VforkResume::Unwind(err) => return Outcome::Unwind(err),
                    VforkResume::ReturnSuccess => (task, switched) = (parent, Some(0)),
                }
            }
            GuestAction::Signal(frame) => {
                let restart =
                    handled.get_or_insert(matches!(ret, Err(SysErr::Restart)) && frame.restarts());
                let Some(abi) = instance_abi(env).await else {
                    syscalls.signal_return(task, None);
                    return Outcome::Unwind(RuntimeError::new("signal delivery before bind"));
                };
                match abi.deliver_signal(env, &frame, *restart).await {
                    Ok(sigreturn) => {
                        syscalls.signal_return(task, sigreturn.mask);
                        *restart = sigreturn.restart;
                    }
                    Err(err) => {
                        syscalls.signal_return(task, None);
                        return Outcome::Unwind(err);
                    }
                }
            }
        }
    }
    if let Some(value) = switched {
        return Outcome::Switched(value);
    }
    let errno = match (ret, handled) {
        (Ok(value), _) => return Outcome::Return(Ok(value)),
        (Err(SysErr::Errno(errno)), _) => errno,
        (Err(SysErr::RestartBlock), None | Some(true)) => return Outcome::Restart,
        (Err(SysErr::Restart | SysErr::RestartNoHand), None | Some(true)) => return Outcome::Rerun,
        (Err(SysErr::Restart | SysErr::RestartNoHand | SysErr::RestartBlock), Some(false)) => {
            Errno::EINTR
        }
    };
    Outcome::Return(Err(errno))
}

async fn instance_abi<S: 'static>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
) -> Option<Arc<dyn AbiInstance<S>>> {
    env.read().await.data().abi.clone()
}

/// Switches the instance back to the vfork parent and lets its ABI resume it.
async fn vfork_resume<S: Control + 'static>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
    parent: TaskId,
    child: TaskId,
) -> VforkResume {
    process::switch(env, parent).await;
    match instance_abi(env).await {
        Some(abi) => abi.vfork_resume(env, child).await,
        None => VforkResume::Unwind(RuntimeError::new("vfork resume before bind")),
    }
}

/// [`complete`] for the generated `wasixv2` shims: the guest's return value (`-errno` on
/// failure), or `None` when the call must run again. A call that saved how to go on
/// (`ERESTART_RESTARTBLOCK`) continues through `restart_syscall` here.
async fn return_to_guest<S: Syscalls + Control + 'static, R: From<i32>>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
    syscalls: &S,
    task: TaskId,
    ret: SysResult<R>,
) -> Option<Result<R, RuntimeError>> {
    let mut ret = ret;
    loop {
        return match complete(env, syscalls, task, ret).await {
            Outcome::Rerun => None,
            Outcome::Restart => {
                let memory = GuestMemory { env };
                let caller = Caller::new(task, &memory);
                ret = Syscalls::restart_syscall(syscalls, &caller)
                    .await
                    .map(R::from);
                continue;
            }
            Outcome::Return(Ok(value)) => Some(Ok(value)),
            Outcome::Return(Err(errno)) => Some(Ok(R::from(-errno.0))),
            Outcome::Switched(value) => Some(Ok(R::from(value))),
            Outcome::Unwind(err) => Some(Err(err)),
            Outcome::Unwinding => Some(Ok(R::from(0))),
        };
    }
}
